cado, el precio final y el momento de aplicación, de modo que cambios posteriores de campaña no alteren el acuerdo aceptado. Los códigos externos de deuda, oferta o plan aportados por la empresa son referencias de conciliación y no llaves técnicas LF. Referencias literales del contrato fuente (no nuevas configuraciones ni autorización de implementación): {\"owner_decision\":\"APPROVED_2026-09-17_V1\",\"physical_creation\":\"BLOCKED_UNTIL_EXISTING_STRUCTURES_RECONCILED_AND_MODEL_APPROVED\",\"conflict_resolution\":\"ONE_APPLICABLE_CAMPAIGN_RESOLVED_SERVER_SIDE_BY_GOVERNED_PRIORITY_AND_CONFIGURATION\",\"eligible_scope_modes\":[\"ALL_ELIGIBLE\",\"SEGMENT\",\"WHITELIST\",\"ADDITIONAL_INCLUDE\",\"EXCLUDE\"],\"existing_rule_reused\":\"REG_LF_BENEFITS_B2B_CAMPAIGN_001\",\"load_template_policy\":\"CAMPAIGN_NOT_REPEATED_IN_STANDARD_PORTFOLIO_LOAD\",\"navigation_candidate\":\"BACKOFFICE_OFFERS_CAMPAIGNS_CHILD_NOT_ROOT\",\"default_stacking_policy\":\"EXCLUSIVE_NO_STACKING\",\"physical_model_candidate\":[\"CAMPAIGN\",\"CAMPAIGN_VERSION\",\"CAMPAIGN_SCOPE\",\"CAMPAIGN_MEMBERSHIP_INCLUDE_EXCLUDE\"],\"stacking_override_policy\":\"ALLOW_ONLY_BY_EXPLICIT_GOVERNED_CONFIGURATION\",\"external_identifier_policy\":{\"partner_debt_code\":\"REFERENCE_ONLY_NOT_LF_PK\",\"partner_plan_code\":\"REFERENCE_ONLY_NOT_LF_PK\",\"partner_offer_code\":\"REFERENCE_ONLY_NOT_LF_PK\"},\"existing_non_reusable_table\":\"lf_ops.system_audit_campaigns\",\"campaign_configuration_scope\":\"SEPARATE_FROM_DEBT_OFFER_PLAN_SCHEDULE_LOAD\",\"existing_non_reusable_reason\":\"SYSTEM_AUDIT_SEMANTICS_NOT_COMMERCIAL_CAMPAIGN\",\"frontend_campaign_resolution\":\"DENY\",\"campaign_minimum_configuration\":[\"CAMPAIGN_NAME\",\"VALID_FROM\",\"VALID_UNTIL\",\"BENEFIT_DEFINITION\",\"FUNDING_SOURCE\",\"ELIGIBILITY_SCOPE\",\"PRIORITY\",\"STACKING_POLICY\",\"STATUS\"],\"generic_json_for_core_relations\":\"DENY_WHEN_SPECIALIZED_RELATIONAL_STRUCTURE_EXISTS\",\"server_side_resolution_required\":true,\"accepted_offer_snapshot_required\